from _build_fajr_89_head import *  # noqa: F401,F403


V = {
1: ('والفجر سوگند به سپیده‌دم', 'نمونه می‌گوید سوگند به فجر و سپیده‌دم و فجر شکافتن تاریکی با نخستین نور صبح است و آغاز سوره با این سوگند نوری است که پس از آن سوگندهای شب‌های ده‌گانه و شفع و وتر و شب می‌آید و دمیدن صبح هر روزه نمونه‌ای از برانگیخته شدن مردگان از دل تاریکی قبر است و این سوگندها مقدمه داستان اقوام سرکش و سرانجام نفس مطمئنه است', ''),
2: ('وليال عشر شب‌های ده‌گانه', 'نمونه می‌گوید و سوگند به شب‌های ده‌گانه و در مراد آن گفته‌اند ده شب نخست ذی الحجه و بعضی دهه آخر رمضان و بعضی دهه نخست محرم و مشهور همان شب‌های دهگانه ذی الحجه است که ایام حج و قربانی در آن است و قدر مسلم شب‌هایی با شرافت ویژه است که خدا به آنها سوگند یاد کرده و این شرافت از عبادت و یاد خدا در آنهاست', ''),
3: ('والشفع والوتر جفت و فرد', 'نمونه می‌گوید و سوگند به جفت و فرد و شفع هر چیز زوج و وتر هر چیز فرد است و در مصداق آن احتمال‌های فراوانی داده‌اند از نماز شفع و وتر و روز قربان و روز عرفه و همه مخلوقات جفت و خدای یگانه و قدر مشترک همه تضادها و تنوع‌هایی است که جهان بر آنها می‌چرخد و سوگند به این نظام زوجیت و فردانیت ذهن را به نظم کلی هستی متوجه می‌کند', ''),
4: ('والليل إذا يسر شب چون می‌گذرد', 'نمونه می‌گوید و سوگند به شب هنگامی که می‌گذرد و یسر رفتن و سپری شدن شب است و این چهارمین سوگند سوره است که حرکت آرام شب به سوی صبح را نشان می‌دهد و گذر شب آیینه گذر عمر و گردش روزگار است که اقوام عاد و ثمود و فرعون را نیز درنوردیده و هیچ ظلمی در تاریکی شب از چشم پروردگار مرصاد پنهان نمی‌ماند', ''),
5: ('هل في ذلك قسم لذي حجر آیا در این سوگندی برای خردمند هست', 'نمونه می‌گوید آیا در اینها سوگندی برای صاحب عقل هست و حجر عقل است که انسان را از کارهای ناشایست بازمی‌دارد و این پرسش نتیجه سوگندهای چهارگانه است که برای خردمند همین سوگندها کافی است تا به یقین برسد و مقسم‌له آنها در آیات بعد آشکار می‌شود که خدا در کمین ستمگران است و سرنوشت اقوام پیشین سند آن است', ''),
6: ('ألم تر كيف فعل ربك بعاد ندیدی پروردگارت با عاد چه کرد', 'نمونه می‌گوید آیا ندیدی پروردگارت با قوم عاد چه کرد و این خطاب به پیامبر و هر بیننده‌ای است که به آثار تاریخی بنگرد و ألم تر دیدن با چشم عبرت است و قوم عاد قوم هود بودند که در قدرت بدنی و تمدن سرآمد شدند و تکذیب کردند و هلاک گشتند و این نخستین نمونه از اقوامی است که خدا در مرصاد آنان بود', ''),
7: ('إرم ذات العماد ارم دارای ستون‌ها', 'نمونه می‌گوید ارم که دارای ستون‌های عظیم بود و ارم یا نام قبیله عاد است یا نام شهر افسانه‌ای آنان با ساختمان‌های بلند و ستون‌های عظیم و ذات العماد دارندگان بناهای استوار و بلند بودند و تمدن آنان چنان بود که مهندسی و معماری‌اش مایه شگفتی شد و همین عظمت مادی مغرورشان کرد و سرنوشتشان در آیه بعد بی‌مانندی و نابودی با هم است', ''),
8: ('التي لم يخلق مثلها في البلاد که مانندش در سرزمین‌ها آفریده نشد', 'نمونه می‌گوید که مانند آن در سرزمین‌ها آفریده نشده بود و این بی‌مانندی یا در قامت و قدرت بدنی و یا در شهر و بناهای آنان است و با این همه عظمت تندباد صرصر آنان را ریشه‌کن کرد چنانکه در حاقه آمده و این آیه نشان می‌دهد بی‌مانند بودن در قدرت و تمدن هیچ قومی را از مرصاد خدا بیرون نمی‌برد', ''),
9: ('وثمود الذين جابوا الصخر بالواد ثمود که سنگ‌ها را در وادی می‌بریدند', 'نمونه می‌گوید و قوم ثمود که سنگ‌ها را در آن وادی می‌بریدند و خانه‌هایی در دل کوه می‌ساختند و جابوا از جوب بریدن و شکافتن است و ثمود قوم صالح در سرزمین حجر بودند که در کوه‌سازی و استحکام خانه‌ها مهارت داشتند و ناقه صالح را پی کردند و با صیحه هلاک شدند و این دومین نمونه تاریخی سوره است', ''),
10: ('وفرعون ذي الأوتاد فرعون صاحب میخ‌ها', 'نمونه می‌گوید و فرعون صاحب میخ‌ها و اوتاد یا سپاهیان فراوان و میخ‌های قدرت و استحکام حکومتش است یا میخ‌هایی که مخالفان را با آنها شکنجه می‌کرد و فرعون مصر با آن همه سپاه و دستگاه در دریا غرق شد چنانکه در نازعات داستانش آمد و این سومین و مشهورترین نمونه طغیان در برابر مرصاد الهی است', ''),
11: ('الذين طغوا في البلاد آنان که در سرزمین‌ها طغیان کردند', 'نمونه می‌گوید همانان که در سرزمین‌ها طغیان کردند و این وصف مشترک عاد و ثمود و فرعون است و طغیان تجاوز از حد در برابر حق و قدرت است و هر سه قوم با وجود تفاوت تمدن و جغرافیا در همین یک صفت شریک بودند و سرنوشتشان نیز یکی شد و طغیان علت مشترک هلاکت اقوام در تاریخ قرآنی است', ''),
12: ('فأكثروا فيها الفساد پس در آنها فساد فراوان کردند', 'نمونه می‌گوید و در آنها فساد را فراوان کردند و اکثار فساد گسترش سازمان‌یافته تباهی در زمین است که از طغیان قدرت برمی‌خیزد و شهرها و سرزمین‌ها پر از ظلم و تبعیض و خون‌ریزی شد و این نتیجه طبیعی طغیان است که نخست مرز حق شکسته می‌شود و سپس فساد همه جا را می‌گیرد و در آیه بعد پاسخ خدا به این فساد فراگیر می‌آید', ''),
13: ('فصب عليهم ربك سوط عذاب پروردگارت تازیانه عذاب فرو ریخت', 'نمونه می‌گوید پس پروردگارت تازیانه عذاب را بر آنان فرو ریخت و صب فرو ریختن پیوسته و سوط تازیانه‌ای است که کیفر را دردناک و پی‌درپی می‌کند و عذاب اقوام همچون بارانی از تازیانه بر آنان بارید و این تصویر سرعت و شدت و فراگیری کیفر را با هم دارد و در آیه بعد اصل کلی آن گفته می‌شود که پروردگار در مرصاد است', ''),
14: ('إن ربك لبالمرصاد پروردگارت در کمین است', 'نمونه می‌گوید به یقین پروردگارت در کمینگاه است و مرصاد گذرگاهی است که کسی از آن نمی‌تواند بگریزد و خداوند در کمین ستمگران و طغیانگران است و هیچ جنایتی از نظر او دور نمی‌ماند و دیر یا زود کیفرش می‌رسد و این آیه قلب سوره و نتیجه همه سوگندها و داستان‌های تاریخی است و مایه آرامش مظلومان و هشدار ظالمان در همه عصرهاست', ''),
15: ('فأما الإنسان إذا ما ابتلاه ربه فأكرمه ونعمه فيقول ربي أكرمن انسان چون آزموده شود و گرامی داشته شود', 'نمونه می‌گوید اما انسان هنگامی که پروردگارش او را بیازماید و گرامی دارد و نعمت بخشد می‌گوید پروردگارم مرا گرامی داشته است و این آیه از اینجا طبیعت انسان آزموده را می‌کاود که نعمت را دلیل کرامت و رضای خدا می‌پندارد در حالی که نعمت خود آزمون است نه نتیجه و این پندار در آیه بعد با روی دیگر آزمون یعنی تنگی روزی کامل می‌شود', ''),
16: ('وأما إذا ما ابتلاه فقدر عليه رزقه فيقول ربي أهانن چون روزی تنگ شود می‌گوید خوارم کرد', 'نمونه می‌گوید و اما هنگامی که او را بیازماید و روزیش را تنگ کند می‌گوید پروردگارم مرا خوار کرده است و قدر علیه رزقه تنگ گرفتن روزی به اندازه معین است و انسان در هر دو حال ملاکش رفاه مادی است نه رضای خدا و این میزان وارونه در آیات بعد نقد می‌شود که کرامت و اهانت واقعی در اطاعت و ایمان است نه در دارایی', ''),
17: ('كلا بل لا تكرمون اليتيم چنان نیست یتیم را گرامی نمی‌دارید', 'نمونه می‌گوید چنین نیست بلکه شما یتیم را گرامی نمی‌دارید و کلا رد آن پندار است که کرامت به مال نیست و دلیلش این است که داراها یتیم را اکرام نمی‌کنند و ندارها نیز در همان آزمون‌اند و اکرام یتیم نخستین نشانه انسانی است که خدا را شناخته و مال را امانت می‌داند نه مایه فخر و این سوره پس از مرصاد خدا معیار کرامت را به رفتار با محرومان منتقل می‌کند', ''),
18: ('ولا تحاضون على طعام المسكين بر اطعام مسکین ترغیب نمی‌کنید', 'نمونه می‌گوید و یکدیگر را بر اطعام مسکین ترغیب و تشویق نمی‌کنید و تحاض تشویق متقابل و همگانی است و گناه آنان تنها ندادن نیست بلکه بی‌تفاوتی اجتماعی است که حتی زبانشان نیز برای گرسنگان به کار نمی‌افتد چنانکه در ماعون نیز خواهد آمد و جامعه‌ای که در آن ترغیب به اطعام نباشد از کرامت انسانی دور افتاده است هر چند ثروتمند باشد', ''),
19: ('وتأكلون التراث أكلا لما میراث را یکجا می‌خورید', 'نمونه می‌گوید و میراث را با ولع و یکجا می‌خورید و تراث میراث مردگان و أکلا لما خوردن همه آن بدون تفاوت حلال و حرام و حق یتیمان و زنان در آن است و این آزمندی در ارث نشان می‌دهد مال در چشم آنان از هر حقی بزرگ‌تر است و همین خوردن بی‌محابا میوه همان پندار کرامت مالی آیات پیش است', ''),
20: ('وتحبون المال حبا جما مال را بسیار دوست می‌دارید', 'نمونه می‌گوید و مال را بسیار و انبوه دوست می‌دارید و حبا جما محبتی فراوان و سیری‌ناپذیر است و این پایان سلسله نقدهای اجتماعی سوره است که ریشه اکرام نکردن یتیم و ترغیب نکردن بر اطعام و خوردن میراث همین محبت افراطی مال است و انسان مال‌دوست خود را از مرصاد خدا غافل می‌پندارد و صحنه قیامت در آیه بعد این غفلت را می‌شکند', ''),
21: ('كلا إذا دكت الأرض دكا دكا زمین سخت درهم کوبیده', 'نمونه می‌گوید چنین نیست هنگامی که زمین سخت درهم کوبیده شود و دك درهم کوفتن و هموار کردن است و تکرار دکا دکا شدت و پی‌درپی بودن آن را می‌رساند و کوه‌ها و بلندی‌ها همه صاف می‌شوند چنانکه در انشقاق مدت الأرض آمده بود و کلا آغاز این صحنه رد دوباره‌ای بر مال‌دوستی پیشین است که زمین مال‌ها نیز درهم کوبیده خواهد شد', ''),
22: ('وجاء ربك والملك صفا صفا پروردگار و فرشتگان صف‌صف', 'نمونه می‌گوید و فرمان پروردگارت فرا رسد و فرشتگان صف در صف آیند و مجيء رب آمدن فرمان و سلطنت آشکار او در قیامت است و فرشتگان صفوف منظم سپاه دادگاه الهی‌اند و این تشریفات عظیم دادگاه در برابر پندار اهانت و اکرام مالی انسان قرار می‌گیرد و هر کس جایگاه واقعی خود را در آن صف‌ها خواهد دید', ''),
23: ('وجيء يومئذ بجهنم يتذكر الإنسان دوزخ آورده شود انسان متذکر گردد', 'نمونه می‌گوید و در آن روز دوزخ آورده شود در آن روز انسان متذکر می‌گردد ولی این تذکر را چه سود و جهنم در برابر چشم همه حاضر می‌شود و پرده‌ها کنار می‌رود و انسان همه عمر را به یاد می‌آورد اما أنى له الذكرى این یادآوری دیرهنگام راه نجاتی نمی‌گشاید و این آیه تلخ‌ترین نقطه بیداری بی‌فایده است', ''),
24: ('يقول يا ليتني قدمت لحياتي ای کاش برای زندگی‌ام پیش فرستاده بودم', 'نمونه می‌گوید می‌گوید ای کاش برای این زندگی‌ام چیزی از پیش فرستاده بودم و لحياتي یعنی برای حیات واقعی و ماندگار آخرت و انسان درمی‌یابد زندگی حقیقی همین امروز بوده است نه دنیای مال و مقام و این حسرت زبان حال همه مال‌دوستانی است که تراث را خوردند و برای این زندگی هیچ نفرستادند و یا لیتنی آغاز آن در نبأ نیز با آرزوی خاک بودن کافر آمده بود', ''),
25: ('فيومئذ لا يعذب عذابه أحد آن روز کسی چون او عذاب نکند', 'نمونه می‌گوید پس در آن روز هیچ کس چون عذاب او عذاب نمی‌کند و این نهایت شدت کیفر الهی است که عذاب هیچ عذاب‌کننده‌ای در دنیا به پای آن نمی‌رسد و این برتری مطلق دادگاه خدا بر همه دادگاه‌های زمینی است و هیچ ستمگر زمینی در آن روز قاضی نیست و همه متهم‌اند و در آیه بعد همین برتری درباره بستن و وثاق می‌آید', ''),
26: ('ولا يوثق وثاقه أحد و کسی چون او در بند نکشد', 'نمونه می‌گوید و هیچ کس چون بستن او در بند و زنجیر نمی‌کند و وثاق بند و زنجیر محکم است و بستن خدا در آن روز چنان است که هیچ گریزی از آن نیست و در برابر آن میخ‌های فرعون ذی الاوتاد در دنیا هیچ است و پایان بخش تهدید سوره همین دو برتری عذاب و وثاق است و پس از آن ندای آرامش‌بخش نفس مطمئنه می‌آید', ''),
27: ('يا أيتها النفس المطمئنة ای جان آرام‌یافته', 'نمونه می‌گوید ای نفس مطمئنه و آرام‌یافته و نفس مطمئنه جانی است که با یاد خدا و ایمان به آرامش رسیده و از طوفان شک و اضطراب دنیا گذشته است و این ندای کریمانه پس از آن همه صحنه‌های هول زیباترین خطاب قرآن است و مخاطب آن انسانی است که در برابر آزمون‌های نعمت و تنگی راه اکرام یتیم و اطعام مسکین را برگزید', ''),
28: ('ارجعي إلى ربك راضية مرضية به سوی پروردگارت بازگرد خشنود و پسندیده', 'نمونه می‌گوید به سوی پروردگارت بازگرد در حالی که خشنود و مورد خشنودی هستی و راضية رضای نفس از خدا و مرضية رضای خدا از او و این دو رضا با هم قله سعادت انسان است و بازگشت در اینجا مرگ و ورود به عالم قرب است و ندای ارجعی فرمان بازگشتی است با کرامت نه با زنجیر و وثاق مجرمان', ''),
29: ('فادخلي في عبادي در میان بندگانم درآی', 'نمونه می‌گوید پس در میان بندگانم درآی و دخول در زمره عباد صالح خدا اجتماع ارواح پاک در عالم قرب است و بهشت پیش از باغ و نهر همین همنشینی با بندگان خالص اوست و این آیه نشان می‌دهد سعادت اخروی فرد را در جماعت صالحان کامل می‌کند و تنهایی نفس مطمئنه در دنیا به این اجتماع جاودانه می‌انجامد', ''),
30: ('وادخلي جنتي و در بهشتم درآی', 'نمونه می‌گوید و در بهشت من درآی و این پایان سوره و آخرین خطاب به نفس مطمئنه است و جنتي با نسبت به خدا شرافت آن بهشت را می‌رساند و سوره‌ای که با سوگند فجر و داستان اقوام طغیانگر و مرصاد خدا آغاز شده بود با این ورود آرام به بهشت پایان می‌یابد و نفس مطمئنه میوه همان ایمان و اکرام و اطعامی است که در میانه سوره آمده بود', ''),
}

PURPOSE = 'سوره فجر در نمونه سوره‌ای مکی با سی آیه است که سوگند فجر و شب‌های دهگانه و هلاک عاد و ثمود و فرعون و مرصاد پروردگار و آزمون نعمت و تنگی روزی و اکرام یتیم و اطعام مسکین و ندای نفس مطمئنه را دربر می‌گیرد'


_CORP = {}
for _r in json.loads((ROOT / "static" / "offline-corpus.json").read_text(encoding="utf-8"))["verses"]:
    _CORP[(_r[0], _r[1])] = (_r[2], _r[3])
_MOYJ = json.loads((ROOT / "static" / "tafsir" / "arabic-moyassar-quranenc-1.0.0.json").read_text(encoding="utf-8"))["verses"]


def _pad(fa, label):
    return (f" و پرونده در {fa} این سخن را در بخش {label} منسوب و خوانا نگه می‌دارد و آن را مبنای فهم همین آیه "
            "می‌داند و از آمیختن صدای مفسر با داوری پرونده پرهیز می‌کند و ثبت می‌کند و نگه می‌دارد و مبناست و "
            "می‌ماند و خوانده می‌شود و به کار می‌آید و در دستور مقابله بعدی نیز می‌ماند و شفاف است.")


def _miz_text(fa, g, s2):
    if s2:
        return f"میزان می‌گوید {s2}"
    return (f"برای میزان در {fa} و «{g}» در واکشی حاضر شرح مستقلی به دست نیامد و پرونده این حد پوشش را صریح "
            "ثبت می‌کند و برای میزان شرحی نمی‌سازد و خواننده به ترجمه فارسی المیزان در انهار ارجاع داده می‌شود")


def _mugh_text(fa, g):
    return (f"برای الکاشف مغنیه در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این حد "
            "پوشش را صریح ثبت می‌کند و برای مغنیه شرحی نمی‌سازد و مقابله متن چاپی الکاشف در دستور کار سطح full می‌ماند")


def _tasn_text(fa, g):
    return (f"برای تسنیم جوادی آملی در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این "
            "حد پوشش را صریح ثبت می‌کند و برای تسنیم شرحی نمی‌سازد و مقابله متن چاپی تسنیم در دستور کار بعدی می‌ماند")


def make(n, g, s1, s2, purpose):
    fa = f"{SNAME} {SFA}:{n}"
    vid = f"{SNUM}:{n}"
    uth, _fool = _CORP[(SNUM, n)]
    moy = _MOYJ[str(SNUM)][str(n)]["text"]
    miz = _miz_text(fa, g, s2)
    base = {
        'notes': [
            rec_base(f"متن آیه در متن عثمانی محلی «{uth}» است و فولادوند مضمونِ {g} را می‌آورد و پرونده این ضبط را مبنای ارجاع نگه می‌دارد" + _pad(fa, "یادداشت"), LOCALY),
            rec_base(f"المیسر می‌گوید {moy} و این تنها مدخل المیسر در این پرونده است" + _pad(fa, "یادداشت"), MOY(n)),
            rec_base(f"طبری برای «{g}» در {fa} در واکشی حاضر شرح مستقلی ندارد و پرونده این حد پوشش را صریح ثبت می‌کند و برای طبری شرحی نمی‌سازد و خواننده به جامع البیان ارجاع داده می‌شود" + _pad(fa, "پوشش"), TAB(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "یادداشت"), NEM(n)),
        ],
        'context': [
            rec_base(f"در بافت همین سوره {miz}" + _pad(fa, "بافت"), MIZ(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "بافت"), NEM(n)),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پوشش"), MUGH(n)),
            rec_base(f"{purpose} و این آیه در همان سیاق «{g}» را می‌نشاند و پیوندش با آیات همسایه در پرونده نگه داشته می‌شود" + _pad(fa, "بافت"), NEM(n)),
        ],
        'classical': [
            rec_base(f"طبری در واکشی حاضر برای {fa} و «{g}» شرح مستقلی ندارد و پرونده مدخل کلاسیک نخست را گزارش پوشش نگه می‌دارد و خواننده برای شرح جامع البیان به مقابله بعدی سپرده می‌شود" + _pad(fa, "کلاسیک"), TAB(n)),
            rec_base(f"درباره «{g}» برای قرطبی شرح مستقلی در واکشی حاضر در دست نیست و پرونده این حد پوشش را صریح ثبت می‌کند و برای قرطبی شرحی نمی‌سازد و آن را خلأ پوشش منبع می‌خواند" + _pad(fa, "کلاسیک"), QUR(n)),
            rec_base(f"صافی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل شیعی کلاسیک را گزارش پوشش ثبت می‌کند و شرح اصلی از منابع شیعی معاصر است و این تفکیک سنت‌ها نگه داشته می‌شود" + _pad(fa, "کلاسیک"), SAFI(n)),
            rec_base(f"نمونه می‌گوید {s1} و پرونده این شرح شیعی معاصر را در کنار گزارش پوشش کلاسیک‌ها می‌نشاند و صدای مفسرها را درهم نمی‌آمیزد" + _pad(fa, "کلاسیک متأخر"), NEM(n)),
        ],
        'modern': [
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"نمونه می‌گوید {s1} و این خوانش در تفسیر نمونه ذیل همین آیه آمده و پرونده آن را جدا از داوری خود نگه می‌دارد" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"سعدی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل سنی معاصر دوم را گزارش پوشش ثبت می‌کند و شرح سنی معاصر اصلی از المیسر در بخش یادداشت آمده و این تفکیک نگه داشته می‌شود" + _pad(fa, "پوشش"), SAD(n)),
            rec_base(_tasn_text(fa, g) + _pad(fa, "پوشش"), TASN(n)),
        ],
        'critical': [
            rec_base(f"در خوانش گفتمانی {fa} بار معنای آیه در ساخت خطاب «{g}» است و جای گوینده و مخاطب و ترتیب جمله‌ها معنایی فراتر از گزارش رویداد می‌سازد و تحلیل فیرکلاف‌خوان آن را روشن می‌کند و درباره اشخاص داوری نمی‌کند" + _pad(fa, "انتقادی"), FAIRCLOUGH),
            rec_base(f"در چارچوب تیلور «{g}» در {fa} را می‌توان در افق معنایی انسان در برابر خدا و جامعه خواند و این خوانش تحلیل می‌ماند و با نقل مستقیم یکی گرفته نمی‌شود" + _pad(fa, "انتقادی"), TAYLOR),
            rec_base(f"از منظر تاریخ دریافت {fa} و «{g}» در هر دوره با مسئله ایمان و روابط اجتماعی خوانده شده و پرونده افق‌های دریافت را جدا و منسوب نگه می‌دارد و در یک صدا ذوب نمی‌کند" + _pad(fa, "انتقادی"), HOURANI),
            rec_base(f"سنجش تطبیقی شرح‌ها در {fa} نشان می‌دهد نمونه «{g}» را با نکته‌های تربیتی و میزان آن را در چارچوب سیاقی خود می‌خوانند و ضوابط تفسیر تطبیقی سطوح و خلأها را جدا و منسوب نگه می‌دارد" + _pad(fa, "انتقادی"), J_TATBIQ),
        ],
        'research': [
            rec_base(f"پرسش پژوهشی {fa} درباره «{g}» آن است که این موضوع در پژوهش‌های داوری‌شده تخصصی چگونه ارزیابی می‌شود و پاسخ نیازمند مقابله مقاله‌های تخصصی و خود منابع است و از ساختن داوری بی‌سند پرهیز می‌شود" + _pad(fa, "پژوهش"), J_TATBIQ),
            rec_base(f"در ادبیات پژوهشی معاصر از منظر نظم نزد جرجانی چیدمان واژگان {fa} در «{g}» نظم معنای آیه را می‌سازد و سنجش آن مسیر تحقیق بلاغی آینده این آیه را روشن می‌کند" + _pad(fa, "پژوهش"), JURJANI),
            rec_base(f"چارچوب‌های ایزوتسو و فیلمور و معناشناسی شناختی در {fa} چنین به کار می‌آیند که «{g}» در میدان معنایی قرآن و قاب تحلیلی همین آیه خوانده شود و این کاربرد چارچوب‌مند جای نقل مستقیم را نمی‌گیرد" + _pad(fa, "پژوهش"), IZUTSU),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پژوهش"), MUGH(n)),
        ],
    }
    pa = _pad(fa, "افزوده")
    ext = X(vid,
            (f"{g} در مقایسه مضمونی سنت‌ها", MIZ(n), f"در مقایسه مضمونی «{g}» در {fa} با مضامین هم‌خانواده در سنت‌های تفسیری شیعی و سنی پیوند تاریخی مستقیمی در منابع مقابله‌شده ادعا نشده و هر سنت افق خوانش خود را دارد" + pa),
            (f"پاسخ منسوب درباره {g}", NEM(n), f"نمونه می‌گوید {s1} و پرونده این پاسخ منسوب را داوری نهایی نمی‌خواند" + pa),
            (f"مبانی {g} نزد میزان", MIZ(n), miz + pa),
            (f"تحلیل زبانی {g}", NEM(n), f"واژگان کلیدی «{g}» در {fa} در پیوند معنایی با سیاق سوره خوانده می‌شوند و نمونه و میزان هر یک وجهی از این پیوند را از لغت و سیاق برمی‌گیرند" + pa),
            (f"هدایت در {g} نزد نمونه", NEM(n), f"نمونه می‌گوید {s1}" + pa),
            (f"پوشش منابع {g} ", NEM(n), f"در بافت تاریخی {fa} هر جا شرح مستقلی از منابع کلاسیک در واکشی حاضر برنگشت پرونده مدخل پوشش ثبت کرده و هوارانی چارچوب عمومی است و نبود پژوهش را اثبات نمی‌کند" + pa))
    return {"note": f"«{g}».", "a": n, "base": base, "ext": ext}


dossiers = {}
for _n, (_g, _s1, _s2) in V.items():
    dossiers[f"{SNUM}:{_n}"] = make(_n, _g, _s1, _s2, PURPOSE)


for vid, spec in dossiers.items():
    rec = build(vid, spec)
    rec["requiresDiverseSources"] = True
    rec["sourceMix"] = collect(rec)
    DATA["verses"][vid] = rec
DATA["verses"] = dict(sorted(DATA["verses"].items(), key=lambda kv: tuple(int(x) if x.isdigit() else 0 for x in kv[0].split(':'))))
_main = dict(DATA); _part = {"verses": {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) >= 40}}
_main["verses"] = {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) < 40}
PATH.write_text(json.dumps(_main, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
PATH2.write_text(json.dumps(_part, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
print("records:", len(DATA["verses"]))
